from policy import retry_delay


def invoice_total(lines):
    # Keep cents: the processor rejects fractional minor units.
    return round(sum(lines), 2)


def send_invoice(client, invoice):
    response = client.send(invoice)
    if response.status == 429:
        return {"retry_after": retry_delay(response.attempt)}
    if response.status >= 500:
        raise RuntimeError("Invoice delivery failed")
    return response.identifier


def receipt_label(number):
    return f"Reçu nº {number}"

